const body = $input.first().json.body || $input.first().json;

const taskId = body.task_id || '';
const updateText = body.update_text || '';
const taskDescription = body.task_description || '';
const employeeName = body.employee_name || '';
const currentStatus = body.status || 'Pending';
const rawChecklist = body.current_checklist || [];

// Normalize checklist to array of objects
const normalizedChecklist = [];
if (Array.isArray(rawChecklist)) {
  for (const item of rawChecklist) {
    if (typeof item === 'string') {
      const isChecked = item.trim().startsWith('[x]');
      let text = item.trim();
      if (text.startsWith('[x]') || text.startsWith('[ ]')) {
        text = text.substring(3).trim();
      }
      normalizedChecklist.push({ text: text, completed: isChecked });
    } else if (typeof item === 'object' && item !== null) {
      normalizedChecklist.push({
        text: item.text || item.step || item.goal || '',
        completed: Boolean(item.completed)
      });
    }
  }
}

return [{
  json: {
    task_id: taskId,
    update_text: updateText,
    task_description: taskDescription,
    employee_name: employeeName,
    current_status: currentStatus,
    checklist: normalizedChecklist
  }
}];

const inputNode = $('Extract Input').first().json;
let dbTask = null;
try {
  const dbItems = $input.all();
  if (dbItems && dbItems.length > 0 && dbItems[0].json && dbItems[0].json.task_id) {
    dbTask = dbItems[0].json;
  }
} catch (e) {}

const taskId = inputNode.task_id;
const updateText = inputNode.update_text;
const taskDescription = (dbTask && dbTask.description) ? dbTask.description : inputNode.task_description;
const employeeName = inputNode.employee_name;
const currentStatus = (dbTask && dbTask.status) ? dbTask.status : inputNode.current_status;

// Prefer DB checklist if valid, otherwise payload checklist
let rawChecklist = (dbTask && dbTask.checklist && Array.isArray(dbTask.checklist) && dbTask.checklist.length > 0)
  ? dbTask.checklist
  : inputNode.checklist;

const checklistItems = [];
if (Array.isArray(rawChecklist)) {
  for (let i = 0; i < rawChecklist.length; i++) {
    const item = rawChecklist[i];
    if (typeof item === 'string') {
      const isChecked = item.trim().startsWith('[x]');
      let text = item.trim();
      if (text.startsWith('[x]') || text.startsWith('[ ]')) {
        text = text.substring(3).trim();
      }
      checklistItems.push({ index: i, text: text, completed: isChecked });
    } else if (typeof item === 'object' && item !== null) {
      checklistItems.push({
        index: i,
        text: item.text || item.step || item.goal || '',
        completed: Boolean(item.completed)
      });
    }
  }
}

// Build checklist summary for LLM
let checklistSummaryText = '';
checklistItems.forEach((item, idx) => {
  const statusStr = item.completed ? '[ALREADY COMPLETED]' : '[PENDING]';
  checklistSummaryText += `${idx + 1}. ${statusStr} ${item.text}\n`;
});

const prompt = `Evaluate the employee progress update for Task ${taskId} against its checklist.\nTask: ${taskDescription}\nChecklist Milestones:\n${checklistSummaryText}\n\nEmployee Update:\n"${updateText}"`;

return [{
  json: {
    task_id: taskId,
    task_description: taskDescription,
    employee_name: employeeName,
    current_status: currentStatus,
    checklist_items: checklistItems,
    checklist_summary: checklistSummaryText,
    update_text: updateText,
    llm_input_prompt: prompt
  }
}];

const rawText = $input.first().json.text || '';
const prepData = $('Prep Payload For LLM').first().json;
const originalItems = prepData.checklist_items || [];

let cleanText = rawText.trim();
const firstBrace = cleanText.indexOf('{');
const lastBrace = cleanText.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) {
  cleanText = cleanText.substring(firstBrace, lastBrace + 1);
}

let parsed = {};
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  parsed = {
    checklist: originalItems.map(it => (it.completed ? `[x] ${it.text}` : `[ ] ${it.text}`)),
    all_completed: false,
    newly_completed_steps: [],
    still_pending_steps: originalItems.filter(it => !it.completed).map(it => it.text),
    explanation: 'AI output could not be parsed; original checklist retained.'
  };
}

let outputChecklist = parsed.checklist || [];
if (!Array.isArray(outputChecklist) || outputChecklist.length !== originalItems.length) {
  outputChecklist = originalItems.map((it, idx) => {
    const matched = Array.isArray(parsed.checklist) ? parsed.checklist.find(c => c.includes(it.text)) : null;
    if (matched && matched.trim().startsWith('[x]')) {
      return `[x] ${it.text}`;
    }
    return it.completed ? `[x] ${it.text}` : `[ ] ${it.text}`;
  });
}

outputChecklist = outputChecklist.map((item, idx) => {
  const origText = originalItems[idx] ? originalItems[idx].text : '';
  let cleanItem = String(item).trim();
  const isDone = cleanItem.startsWith('[x]');
  if (cleanItem.startsWith('[x]') || cleanItem.startsWith('[ ]')) {
    cleanItem = cleanItem.substring(3).trim();
  }
  const finalText = cleanItem || origText;
  return isDone ? `[x] ${finalText}` : `[ ] ${finalText}`;
});

const totalItems = outputChecklist.length;
const completedCount = outputChecklist.filter(item => item.startsWith('[x]')).length;
const allCompleted = (totalItems > 0 && completedCount === totalItems);

let newStatus = prepData.current_status;
if (allCompleted) {
  newStatus = 'Completed';
} else if (newStatus !== 'Completed' && newStatus !== 'Delayed') {
  newStatus = 'Active';
}

return [{
  json: {
    task_id: prepData.task_id,
    checklist: outputChecklist,
    status: newStatus,
    all_completed: allCompleted,
    completed_count: completedCount,
    total_count: totalItems,
    newly_completed_steps: parsed.newly_completed_steps || [],
    still_pending_steps: parsed.still_pending_steps || [],
    explanation: parsed.explanation || (allCompleted ? 'All milestones completed!' : `${completedCount} of ${totalItems} milestones completed.`),
    last_updated: new Date().toISOString(),
    updated_by: 'AI Progress Evaluator'
  }
}];
